<?php $users=db()->query('SELECT id,username,email,full_name,role,status,created_at FROM users ORDER BY created_at')->fetchAll();?>
<div class="page-heading"><div><p class="eyebrow">AKSES SISTEM</p><h1>Pengguna</h1><p class="subheading">Atur akun kasir dan administrator Ruang Seduh.</p></div></div><div class="admin-layout"><section class="panel"><div class="panel-heading"><div><h2>Akun terdaftar</h2><p><?= count($users) ?> pengguna</p></div></div><div class="table-scroll"><table><thead><tr><th>Nama lengkap</th><th>Username / email</th><th>Peran</th><th>Status</th><th>Bergabung</th><th></th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><form method="post" class="user-name-form"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="update-name"><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><input class="user-name-input" type="text" name="full_name" value="<?= e($u['full_name']) ?>" maxlength="100" required aria-label="Nama lengkap <?= e($u['username']) ?>"><button class="user-name-save" type="submit">Simpan</button></form></td><td><?= e($u['username']) ?><small class="table-sub"><?= e($u['email']) ?></small></td><td><?= $u['role']==='admin'?'Administrator':'Kasir / waiter' ?></td><td><span class="status <?= $u['status']?'done':'cancelled' ?>"><?= $u['status']?'Aktif':'Nonaktif' ?></span></td><td><?= date('d M Y',strtotime($u['created_at'])) ?></td><td><?php if((int)$u['id']!==(int)current_user()['id']):?><form method="post"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="toggle-user"><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><button class="link-button" type="submit"><?= $u['status']?'Nonaktifkan':'Aktifkan' ?></button></form><?php else:?>Akun Anda<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel compact-form"><h2>Buat akun</h2><p>Kredensial disimpan dalam bentuk hash aman.</p><form method="post" class="stack-form"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><label>Nama lengkap<input name="full_name" required maxlength="100"></label><label>Username<input name="username" required minlength="3" maxlength="40" pattern="[A-Za-z0-9_.-]+" autocomplete="off"></label><label>Email<input type="email" name="email" required maxlength="160"></label><label>Kata sandi<input type="password" name="password" required minlength="8" autocomplete="new-password"></label><label>Hak akses<select name="role"><option value="kasir">Kasir / waiter</option><option value="admin">Administrator</option></select></label><button class="button primary full">Buat akun pengguna</button></form></section></div>
